class WebsiteHandler(BaseHTTPRequestHandler):
    def send_html(self, content, status=200):
        data = content.encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/" or self.path.startswith("/?"):
            self.send_html(page())
        else:
            self.send_html("<h1>404 - Page Not Found</h1>", 404)

    def do_POST(self):
        if self.path != "/contact":
            self.send_html("<h1>404 - Page Not Found</h1>", 404)
            return

        length = int(self.headers.get("Content-Length", 0))
        raw = self.rfile.read(length).decode("utf-8")
        data = parse_qs(raw)

        name = data.get("name", [""])[0].strip()
        phone = data.get("phone", [""])[0].strip()
        service = data.get("service", [""])[0].strip()
        message = data.get("message", [""])[0].strip()

        # Save enquiries locally.
        with open("enquiries.txt", "a", encoding="utf-8") as f:
            f.write(
                "\n==============================\n"
                f"Name: {name}\n"
                f"Phone: {phone}\n"
                f"Service: {service}\n"
                f"Message: {message}\n"
                "==============================\n"
            )

        self.send_html(
            page("Thank you! Your enquiry has been received. "
                 "The SSV Group team can contact you shortly.")
        )


def run_server():
    server = HTTPServer((HOST, PORT), WebsiteHandler)
    print("=" * 55)
    print("       SHRI SAI VENKATESH GROUP")
    print("       Premium Website")
    print("=" * 55)
    print(f"Open: http://{HOST}:{PORT}")
    print("Press CTRL+C to stop.")
    server.serve_forever()


if __name__ == "__main__":
    thread = threading.Thread(target=run_server, daemon=True)
    thread.start()
    webbrowser.open(f"http://{HOST}:{PORT}")

    try:
        while True:
            threading.Event().wait(3600)
    except KeyboardInterrupt:
        print("\nWebsite stopped.")
